public static Command flashLights() {
    return Commands.startEnd(
        () -> lights.setOn(true),
        () -> lights.setOn(false),
        lights);
}

public static Command shoot() {
    return Commands.startEnd(
        () -> shooter.setWantedState(ShooterStates.SHOOT),
        () -> shooter.setWantedState(ShooterStates.IDLE),
        shooter);
}
